#!/usr/bin/env python3
"""Build offline dashboard, classroom guides and notebooks from checked analytical outputs."""
import base64,hashlib,json
from pathlib import Path
from build_catalog import BASE,read,write

CASES={
'uci-retail':dict(title='La venta que cambió de puesto',hook='Una tienda quiere destacar sus productos estrella. ¿Lo que más factura sigue siendo lo que más deja al registrar créditos?',choices='D31-A · neto por producto; D31-E · ranking bruto/neto; D31-B · líneas frente a facturas sin ID.',finding='En 300 facturas de noviembre de 2011: bruto 95,755.66 GBP, créditos 4,426.64 GBP y neto firmado 91,329.02 GBP. 1,875 productos cambian de posición; 30.1% de líneas y 12.7% de facturas carecen de ID de cliente.',limits='La muestra se seleccionó por factura, no por cliente; una nota negativa no está emparejada con su venta original. No hay costos para calcular utilidad. No inferir perfil social de clientes a partir de un ID ausente.',alt='Barras de bruto positivo y neto firmado para los mismos diez productos.',concept='Denominadores y definiciones de una métrica económica',paths='Camino 1: sumar importes firmados por producto mediante groupby. Camino 2: reconstruir bruto menos créditos con un acumulador Decimal independiente. Sensibilidad: repetir sin duplicados y contar faltantes por línea/factura.',minimum_fields='InvoiceNo, StockCode, Quantity, UnitPrice, InvoiceDate, Country, customer_id_missing',choice='D31-A'),
'nba-elo':dict(title='El partido contado dos veces',hook='Un pronóstico parece tener miles de observaciones. Antes de confiar en él, averigua qué significa una fila y qué información podía conocer antes del encuentro.',choices='D10-D2 · victoria local por fase; D10-E · calibración del pronóstico y filas espejo.',finding='2,622 filas representan 1,311 partidos. En esta temporada histórica, la victoria local observada es 57.6%. El Brier del pronóstico previo es 0.20844 frente a 0.25 de una probabilidad constante de 0.5.',limits='Es una temporada histórica, incluidos playoffs. El bootstrap por fecha no elimina toda dependencia por equipos/series. La comparación por fase mezcla composición y selección de equipos. Marcadores y elo_n son posteriores y no son predictores permitidos.',alt='Calibración de pronósticos previos frente a fracción observada; tamaño de punto proporcional a partidos.',concept='Unidad independiente, calibración y fuga de información',paths='Camino 1: comparar tasas de victoria local entre fases con conteos y sensibilidad por fecha. Camino 2: deduplicar por game_id, evaluar forecast previo y verificar Brier por perspectiva espejo. Contraste adversarial: contar filas como partidos y revisar elo_n.',minimum_fields='game_id, team_id, _iscopy, date_game, game_location, forecast, elo_i, elo_n, pts, opp_pts, is_playoffs',choice='D10-E'),
'bob-ross-elementos':dict(title='Los árboles que faltaban',hook='La intuición dice que todos sus cuadros tienen árboles. ¿Basta mirar algunos ejemplos? Después intenta organizar una exposición en cuatro salas y cuestiona tus propios grupos.',choices='D85-D1 · árboles; D85-D2 · montañas y nieve; D85-C · grupos de motivos; D85-B · invitados frente al anfitrión.',finding='Entre 381 episodios del anfitrión hay 36 sin TREE ni TREES registrados. El clustering propuesto cambia fuertemente al pasar de Jaccard a Euclídea: ARI −0.0458. La etiqueta de un motivo no describe píxeles ni su cantidad.',limits='Se analizan etiquetas humanas de episodios, no todas las pinturas. Cuatro grupos es una restricción narrativa, no un número descubierto de estilos naturales. La discrepancia de agrupamientos es un resultado que debe mostrarse.',alt='Heatmap de prevalencia de doce motivos en cuatro grupos propuestos, con tamaño de cada grupo.',concept='Contraejemplos, representación de datos y estabilidad de grupos',paths='Camino 1: tabla de frecuencias y contraejemplos, incluyendo/excluyendo invitados. Camino 2: clustering jerárquico con Jaccard y contraste con Euclídea; excluir siempre identificador y temporada como features.',minimum_fields='EPISODE, GUEST, TREE, TREES, MOUNTAIN, MOUNTAINS, SNOW, SNOWY_MOUNTAIN y motivos declarados en run_pilots.py',choice='D85-D1')
}

LABELS={'publisher':'Productor','original_category':'Categoría original del repositorio','origin':'Procedencia del inventario','reference_period_declared':'Periodo declarado','formats_declared':'Formatos declarados','variables_declared':'Variables declaradas','keys_proposed':'Claves propuestas, no PK validadas','access':'Acceso','license':'Licencia y alcance','universe_size':'Tamaño del universo','start_date_verified':'Fecha inicial comprobada','end_date_verified':'Fecha final comprobada','last_updated_verified':'Última actualización comprobada','quotas':'Cuotas','quality':'Calidad','schema_changes':'Cambios de esquema','privacy':'Privacidad','snapshot':'Snapshot','hypothesis':'Hipótesis','objective':'Objetivo','metric':'Métrica','denominator':'Denominador','period':'Periodo y corte','required_fields':'Campos necesarios','required_additional_data':'Datos adicionales','technique':'Técnica','route_simple':'Camino mínimo','route_advanced':'Camino alternativo','visualizations':'Visualizaciones','adversarial_test':'Prueba adversarial','refutation_criterion':'Criterio de refutación','blockers':'Bloqueadores','pilot_inference_limits':'Límites de la ejecución','curiosity_narrative':'Curiosidad y narrativa','originality':'Originalidad','data_quality_availability':'Evidencia de calidad y disponibilidad','business_social_impact':'Impacto de negocio/social','learning_value':'Aprendizaje','technique_diversity':'Diversidad de técnicas','interesting_results':'Potencial de resultados interesantes','classroom_reproducibility':'Reproducción en aula','execution_maintenance_cost':'Menor costo de ejecución/mantenimiento','question':'Pregunta','methodology':'Método','result':'Resultado','limitations':'Limitaciones','dataset_match':'Correspondencia del dataset','evidence':'Evidencia'}

def cell(kind,text):
    d={'cell_type':kind,'id':hashlib.sha256(text.encode()).hexdigest()[:12],'metadata':{},'source':text.splitlines(keepends=True)}
    if kind=='code':d.update(execution_count=None,outputs=[])
    return d
def notebook(sid,c):
    return {'nbformat':4,'nbformat_minor':5,'metadata':{'kernelspec':{'name':'python3','display_name':'Python 3','language':'python'},'language_info':{'name':'python'},'title':c['title']},'cells':[
        cell('markdown',f"# {c['title']}\n\n{c['hook']}\n\n**45 minutos · Delegar, verificar y firmar.** El entorno y los datos se preparan antes de clase. Si se reinicia la sesión, ejecuta desde la primera celda. No hay claves ni llamadas a modelos en el cuaderno.\n\nRutas disponibles: {c['choices']}\n\n**Antes de ejecutar:** registra una predicción y vota. Las salidas se revelan después de tu elección."),
        cell('code',f"from pathlib import Path\nimport json, importlib.util\n\n# Cambia únicamente estas dos frases con tu grupo.\nPREGUNTA = {c['choice']!r}\nPREDICCION = ''\n\n# El docente prepara la carpeta antes de clase; no descargamos ni instalamos aquí.\nroots = [Path.cwd(), *Path.cwd().parents]\nLAB_ROOT = next((p for r in roots for p in (r/'discovery_labs', r) if (p/'catalog/questions.json').exists() and (p/'scripts/run_pilots.py').exists()), None)\nif LAB_ROOT is None:\n    raise RuntimeError('No encuentro el paquete offline. Pide al docente la carpeta preparada antes de continuar.')\nbank = json.loads((LAB_ROOT/'catalog/questions.json').read_text())\navailable = {{q['id']: q for q in bank if q['source_id'] == {sid!r} and q['status'] == 'TECHNICALLY_EXECUTED'}}\nif PREGUNTA not in available:\n    raise ValueError('Elige una de las rutas habilitadas de este piloto.')\nq = available[PREGUNTA]\nprint('Pregunta:', q['question'])\nprint('Métrica:', q['metric'])\nprint('Denominador:', q['denominator'])"),
        cell('markdown',f"## Dos caminos, una elección humana\n\n{c['paths']}\n\nPide a tu copiloto que critique ambos caminos. Escribe en tu registro cuál eliges, qué columna podría faltar y qué observación refutaría tu predicción. Puedes cambiar la pregunta si no puede responderse con estos datos.\n\nVerifica dos filas y comprueba un caso a mano antes de mirar la salida."),
        cell('code',f"if not PREDICCION.strip():\n    raise ValueError('Registra primero tu predicción en la celda inicial y vuelve a ejecutarla.')\nspec = importlib.util.spec_from_file_location('lab_runner', LAB_ROOT/'scripts/run_pilots.py')\nlab = importlib.util.module_from_spec(spec)\nspec.loader.exec_module(lab)\ndata, manifest = lab.load({sid!r})\nprint('Filas verificadas:', len(data))\nprint('Columnas:', ', '.join(data.columns))\nprint('Hash coincide:', manifest['snapshot_sha256'] == lab.sha(LAB_ROOT/'pilots'/{sid!r}/'data/snapshot.csv'))\nfrom IPython.display import display\ndisplay(data.head(4))"),
        cell('markdown','## Ejecutar y cuestionar\n\nLa ejecución calcula también sensibilidades predefinidas. Usa sólo la evidencia pertinente a la pregunta votada. No cambies de hipótesis después de ver un resultado sin registrarlo como exploración nueva.'),
        cell('code',f"result = lab.run({sid!r}, LAB_ROOT/'output')\nfor name in ('invoices', 'eligible_rows', 'unique_games', 'home_win_rate', 'brier', 'host_episodes', 'tree_counterexample_count', 'jaccard_euclidean_ARI'):\n    if name in result: print(name, ':', result[name])\nfrom IPython.display import Image\nchart = ('denominators.png' if PREGUNTA == 'D31-B' else 'phases.png' if PREGUNTA == 'D10-D2' else 'beliefs.png' if PREGUNTA in ('D85-D1','D85-D2','D85-B') else 'comparison.png')\ndisplay(Image(filename=str(LAB_ROOT/'output'/{sid!r}/chart)))\nif PREGUNTA == 'D10-D2': display(lab.pd.DataFrame(result['phases']))\nif PREGUNTA == 'D85-D1': display(lab.pd.read_csv(LAB_ROOT/'output'/{sid!r}/'counterexamples.csv').head())\nif PREGUNTA == 'D85-B': display(lab.pd.DataFrame([{{'grupo':'Anfitrión','episodios':result['host_episodes'],'fracción con árboles':result['host_tree_fraction']}},{{'grupo':'Invitados','episodios':result['guest_episodes'],'fracción con árboles':result['guest_tree_fraction']}}]))\nprint('Prueba en contra:', result['adversarial_result'])\nprint('Límites:', result['inference'])"),
        cell('markdown','## Verificar y firmar\n\n1. Comprueba dos filas, un cálculo a mano y los totales de entrada/salida.\n2. Abre la tabla CSV generada y contrasta la prueba adversarial.\n3. Registra qué le corregiste a la IA y si tu predicción se sostiene.\n4. Firma una afirmación con magnitud, denominador, límite y decisión.\n\nSi no alcanza el dato, explica exactamente qué falta. No compartas nombres ni respuestas personales en el repositorio público. Esta actividad es formativa y no modifica tus calificaciones.')
    ]}

def main():
    for sid,c in CASES.items():
        folder=BASE/'pilots'/sid;m=read(folder/'data/manifest.json');r=read(BASE/'output'/sid/'results.json')
        (folder/'ALUMNO.md').write_text(f"# {c['title']}\n\n{c['hook']}\n\n**Votación:** {c['choices']}\n\n**Concepto:** {c['concept']}.\n\n{c['paths']}\n\nCampos mínimos: {c['minimum_fields']}.\n\nLee [el registro de investigación](../../templates/ALUMNO.md), completa tu predicción y abre [el cuaderno](alumno.ipynb). No mires resultados antes de apostar.\n\nSi reinicias sesión, vuelve a correr desde el principio. Para trabajar offline, usa data/snapshot.csv y el script de la carpeta scripts.\n")
        (folder/'DOCENTE.md').write_text(f"# Guion · {c['title']}\n\nSeguir [la secuencia de 45 minutos](../../templates/DOCENTE.md).\n\n## Preparación\n\nConcepto principal: {c['concept']}. Audiencia: principiantes con IA copiloto; actividad opcional, sin evaluación formal. Comprueba {m['rows']} filas, {len(m['columns'])} columnas, {m['snapshot_bytes']:,} bytes y SHA256 `{m['snapshot_sha256']}`.\n\n## Elección real\n\n{c['choices']}\n\n{c['paths']}\n\n## Evidencia de referencia, después de la predicción\n\n{c['finding']}\n\n{c['limits']}\n\nPedir dos comprobaciones independientes, permitir una objeción explícita a la IA y cerrar con decisión humana. No llamar rentable al neto, muestra independiente a una fila espejo ni natural a un grupo impuesto.\n\n## Ensayo\n\nEstado: PENDIENTE. Se necesita la sesión humana observada, no más tiempo de CPU. Registrar intervalos, incidentes, ruta elegida y cierre, según la plantilla.\n")
        (folder/'README.md').write_text(f"# {c['title']}\n\n{c['hook']}\n\n**Estado:** piloto técnico ejecutado y reproducible offline; NO listo para clase hasta ensayo humano de 45 minutos y revisión docente.\n\n- [Alumno](ALUMNO.md) · [Cuaderno Python](alumno.ipynb) · [Docente](DOCENTE.md)\n- [Snapshot](data/snapshot.csv) · [Procedencia, licencia y hash](data/manifest.json)\n\n[Diccionario y unidades](DICCIONARIO.md).\n\n## Elecciones disponibles\n\n{c['choices']}\n\n{c['paths']}\n\n## Reproducción\n\nDesde la raíz del repositorio, con dependencias preparadas fuera de clase:\n\n```bash\npython discovery_labs/scripts/run_pilots.py --case {sid}\n```\n\nLas tablas, el gráfico y results.json se crean en `discovery_labs/output/{sid}/`; no hay descargas en ejecución. El snapshot es también la alternativa offline. Si falla el entorno, el dashboard contiene la evidencia calculada para discusión, con su alcance.\n\n## Resultado comprobado\n\n{c['finding']}\n\n## Límites\n\n{c['limits']}\n\nAtribución: {m['attribution']}. {m['license']}. La licencia se aplica a datos, no a medios de terceros.\n")
        write(folder/'alumno.ipynb',notebook(sid,c))
    bundle={'sources':read(BASE/'catalog/sources.json'),'questions':read(BASE/'catalog/questions.json'),'antecedents':read(BASE/'catalog/antecedents.json'),'ranking':read(BASE/'catalog/ranking.json'),'audit':read(BASE/'catalog/audit_summary.json'),'labels':LABELS,'pilots':[]}
    for sid,c in CASES.items():
        image=base64.b64encode((BASE/'output'/sid/'comparison.png').read_bytes()).decode()
        second={'uci-retail':'denominators.png','nba-elo':'phases.png','bob-ross-elementos':'beliefs.png'}[sid]
        second_image=base64.b64encode((BASE/'output'/sid/second).read_bytes()).decode()
        bundle['pilots'].append({**c,'source_id':sid,'image':'data:image/png;base64,'+image,'secondary_image':'data:image/png;base64,'+second_image,'results':read(BASE/'output'/sid/'results.json')})
    data=json.dumps(bundle,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')
    html=(BASE/'dashboard/template.html').read_text().replace('__DATA__',data)
    (BASE/'dashboard/index.html').write_text(html)
    print('Dashboard offline:',BASE/'dashboard/index.html',len(html.encode()),'bytes; 3 guiones + 3 cuadernos')

if __name__=='__main__':main()
